  'This syllabus preserves a French New Wave-to-streaming arc while adding postwar art cinema, Third Cinema, African/Latin American/Middle Eastern cinemas, feminist/queer/Black/Indigenous/decolonial histories, video/time-based media, archive practice, and a research capstone.',
  $fh2json${"slug": "film-history-ii", "title": "Film History II", "description": "This syllabus preserves a French New Wave-to-streaming arc while adding postwar art cinema, Third Cinema, African/Latin American/Middle Eastern cinemas, feminist/queer/Black/Indigenous/decolonial histories, video/time-based media, archive practice, and a research capstone.", "topics": [{"id": "55653fc7-cdc6-4cc0-a779-948921a5bda5", "type": "topic", "title": "Modern Film History as Global Method", "description": "This section frames Film History II as a study of postwar and contemporary cinema through movements, institutions, technologies, audiences, archives, and global power.", "children": [{"id": "f7898ad7-3a9a-42a8-ae01-775ef7d406a3", "type": "subtopic", "title": "From national cinema to transnational cinema", "children": [{"id": "e7a4fb3e-88a4-4603-ba12-279ab2d778a1", "type": "concept", "title": "Co-productions and festival circuits"}, {"id": "2e6e5973-8000-4bdd-a497-6ae2082a0f4d", "type": "concept", "title": "Migration, exile, and diasporic filmmaking"}, {"id": "c447c24c-227f-4f47-8ee8-bb37d0174975", "type": "concept", "title": "Global circulation of style, labor, capital, and taste"}], "description": "Students learn why modern film history cannot be told only as separate national stories."}, {"id": "e3a03db1-ed25-48c5-b5a0-680390c5569e", "type": "subtopic", "title": "Historiography and critical method", "children": [{"id": "576617df-57b2-44f7-bab5-c2ffbb2ab6e9", "type": "concept", "title": "Primary and secondary sources"}, {"id": "04a66559-3ff5-4ee4-9bfd-f213272904f8", "type": "concept", "title": "Close analysis with historical context"}, {"id": "cebf8ee0-a132-487f-9781-885bfcbc9db4", "type": "concept", "title": "Canon critique and archive awareness"}], "description": "The point is to make historical arguments from films, criticism, industry evidence, and reception."}, {"id": "f39433d0-7a38-4648-9b35-08251b694bb5", "type": "subtopic", "title": "Modernity, decolonization, and media change", "children": [{"id": "b54ee792-fcf9-4759-956d-3efd4f63ee6d", "type": "concept", "title": "Cold War and postcolonial contexts"}, {"id": "2a9cf2f8-b446-49b2-9699-7bde921b72da", "type": "concept", "title": "Mass media and spectatorship"}, {"id": "083c3ea4-ee9e-4fa7-978b-fc622df732b2", "type": "concept", "title": "Technology as historical force"}], "description": "Students connect cinema to postwar politics, decolonization, television, video, digital media, and globalization."}]}, {"id": "561cd292-ca4f-4a91-a561-1291105f065a", "type": "topic", "title": "Postwar Film Culture and International Art Cinema", "description": "This section shows how postwar festivals, critics, art houses, auteurs, and cinephile institutions created a new international film culture.", "children": [{"id": "e9f825d9-30cf-486e-a55f-eafe54dbdd8a", "type": "subtopic", "title": "Festival and art-house systems", "children": [{"id": "89732ba0-ee49-4e1d-b89c-5ed4336f9a69", "type": "concept", "title": "Cannes, Venice, Berlin, and festival prestige"}, {"id": "85b7fe65-8c8b-4434-9dfe-b460b7667c84", "type": "concept", "title": "Art-house distribution and subtitled cinema"}, {"id": "8b54b7d7-b8d6-4d56-91f7-e9434f12e386", "type": "concept", "title": "Cine-clubs, critics, and film journals"}], "description": "Students learn how exhibition institutions shaped what counted as serious cinema."}, {"id": "f6e32818-29fe-4e9c-ad39-bb19f40a03c3", "type": "subtopic", "title": "Auteurs and modernist narration", "children": [{"id": "9271812b-4f85-499a-9f8f-19678669258c", "type": "concept", "title": "Authorial signature"}, {"id": "eec7b0dc-c603-4cda-a45c-454bb28b8304", "type": "concept", "title": "Psychological ambiguity"}, {"id": "040b1e7c-1db9-4400-9f3f-74e29e1f35b2", "type": "concept", "title": "Ellipsis, reflexivity, and open form"}], "description": "The gist is to study ambiguity, style, subjectivity, and open endings as historical art-cinema conventions."}, {"id": "302cb0f4-55f1-4210-8be0-b64bd5042831", "type": "subtopic", "title": "Postwar cultural memory", "children": [{"id": "08f82c0f-da93-47ad-bb3a-383face35dab", "type": "concept", "title": "War memory and ruins"}, {"id": "2b34fec6-91ca-42fe-8a73-713277fc5cdb", "type": "concept", "title": "Existentialism and alienation"}, {"id": "53cb1f85-dad6-4f75-9ee2-9833bdfbbbe1", "type": "concept", "title": "New spectators and cinephilia"}], "description": "Students connect modern cinema to trauma, reconstruction, and changing social life."}]}, {"id": "611f3fd1-043d-4374-9d2a-c595f8241b66", "type": "topic", "title": "The French New Wave", "description": "The French New Wave is a central case in modern film history because it linked criticism, cinephilia, low-budget production, youth culture, and formal experimentation.", "children": [{"id": "227aa379-deb4-4ac5-9157-86a52993a006", "type": "subtopic", "title": "Cahiers du Cinema and auteur politics", "children": [{"id": "bdfacdc8-b310-4f18-8016-3662916a5458", "type": "concept", "title": "Auteur theory and mise-en-scene criticism"}, {"id": "70f7c9e0-6784-4e2e-b35e-bf46631593ab", "type": "concept", "title": "Truffaut, Godard, Chabrol, Rohmer, and Rivette"}, {"id": "8122f904-23e5-4fdb-bcdd-211142e1240d", "type": "concept", "title": "Cinephilia as method"}], "description": "Students learn how critics became filmmakers and reframed film history through authorship."}, {"id": "ac20e9b5-5d57-474f-babf-e5530b122223", "type": "subtopic", "title": "Style and production", "children": [{"id": "595dd502-ae1e-4fef-80cd-8c4a7ec52454", "type": "concept", "title": "Lightweight equipment and location work"}, {"id": "c65fb7ff-175d-4b13-b44e-cc44d136e76f", "type": "concept", "title": "Fragmented editing and direct address"}, {"id": "9316cd17-ebed-4924-ae78-43d5c0f0e161", "type": "concept", "title": "Youth culture, urban space, and spontaneity"}], "description": "The point is to connect handheld cameras, location shooting, jump cuts, and improvisation to economic and cultural change."}, {"id": "33feade8-abea-4345-8541-e6994301574d", "type": "subtopic", "title": "Legacy and critique", "children": [{"id": "c10afeb4-32d0-4d8b-beab-99fcb2025d82", "type": "concept", "title": "Global new-wave influence"}, {"id": "4e0fff63-4c2f-471b-a290-892506b00e0c", "type": "concept", "title": "Gender and authorship critiques"}, {"id": "76ce37ed-be95-4117-9376-02ff75a2cbc8", "type": "concept", "title": "New Wave afterlives in independent cinema"}], "description": "Students evaluate both the movement's influence and its limits."}]}, {"id": "b4f00a7c-03a5-460e-a134-7f9a4d09135b", "type": "topic", "title": "New Waves Around the World", "description": "This section expands the New Wave concept into a comparative study of modern cinemas in political, cultural, and institutional transformation.", "children": [{"id": "a435fa48-e3e5-4fc8-8afc-9673baf3ddcc", "type": "subtopic", "title": "European new waves", "children": [{"id": "d7918fc5-4c78-41ee-a5c5-3298fe4e0c99", "type": "concept", "title": "Czech New Wave"}, {"id": "6e4dcc1d-fa0c-4303-be37-7b33efb3cda1", "type": "concept", "title": "British kitchen-sink realism"}, {"id": "d9116c90-0c28-46be-a669-c6c538560dac", "type": "concept", "title": "New German Cinema"}], "description": "Students compare new film movements that challenged studio tradition and postwar consensus."}, {"id": "f530f668-958e-47b4-9b83-7ae960178294", "type": "subtopic", "title": "Third Cinema and political modernism", "children": [{"id": "612ae51d-9c29-4c47-9fcb-278dcbdcf3a6", "type": "concept", "title": "Latin American Third Cinema"}, {"id": "1e408874-c22f-4053-8dab-3f1ee69c33f1", "type": "concept", "title": "Manifestos and militant spectatorship"}, {"id": "2a97b038-7305-4405-b0b4-94d7360719cc", "type": "concept", "title": "Imperfect cinema and political urgency"}], "description": "The gist is to examine cinema as anti-colonial, revolutionary, and collective practice."}, {"id": "f87db34b-1528-44bf-9557-b4b1909260c1", "type": "subtopic", "title": "Regional modernisms", "children": [{"id": "14ed0fd5-826e-4861-89d3-cf1e40d10139", "type": "concept", "title": "Japanese New Wave"}, {"id": "91b60540-0191-4f53-b9ec-ba45494ff903", "type": "concept", "title": "Indian parallel cinema"}, {"id": "c0bd7634-fa91-4402-a657-fd7581b58db0", "type": "concept", "title": "African and Middle Eastern modernist cinemas"}], "description": "Students study modern cinema beyond a Euro-American frame."}]}, {"id": "f72dd010-9f0f-4487-a0af-cf8764e8f246", "type": "topic", "title": "New Hollywood, 1967-1980", "description": "New Hollywood marks a major transformation in American cinema through youth audiences, auteur branding, genre revision, political disillusionment, and industry crisis.", "children": [{"id": "0ceab760-2bb4-442b-bbd3-e717caea4aff", "type": "subtopic", "title": "Industrial crisis and opportunity", "children": [{"id": "b65140a8-0683-45e2-84bb-a0ade0811313", "type": "concept", "title": "Paramount decrees and studio restructuring"}, {"id": "497d55a8-9032-4473-9cda-3f6fe8a95b43", "type": "concept", "title": "Television competition and youth markets"}, {"id": "1b6279fa-e5bb-43f1-96dd-83ce416ff615", "type": "concept", "title": "Ratings system and changing censorship"}], "description": "Students learn how declining studio control opened space for new filmmakers and subjects."}, {"id": "33841f5b-6cb5-4b48-82b2-b8eb016881ff", "type": "subtopic", "title": "Auteurism and genre revision", "children": [{"id": "597a457b-12e5-4aa1-a352-640fd477b257", "type": "concept", "title": "Road movie, western, crime, horror, and melodrama revision"}, {"id": "69d4feeb-bf59-4426-b3e4-9d91054084f5", "type": "concept", "title": "Ambiguous protagonists and antiheroes"}, {"id": "9082ba62-cca9-4ff5-ba12-e0f0b62746c1", "type": "concept", "title": "Violence, sexuality, and political distrust"}], "description": "The point is to connect European art cinema and American genre tradition."}, {"id": "7b1cb957-f3ff-4a92-aa95-d64ce7878e7e", "type": "subtopic", "title": "Race, gender, and counterculture", "children": [{"id": "4bf4c4ac-10e9-41c7-a377-08604cd0e2d6", "type": "concept", "title": "Blaxploitation and independent Black cinema"}, {"id": "6e7c8a4e-5391-438c-99f4-f460c80a7179", "type": "concept", "title": "Women filmmakers and feminist critique"}, {"id": "826ca07d-a2b6-4101-a4a6-6a551b2c72dd", "type": "concept", "title": "Vietnam, Watergate, and social fracture"}], "description": "Students examine the period's promises and blind spots."}]}, {"id": "d7864845-513e-4e96-a4a0-b3e843c6c830", "type": "topic", "title": "The Blockbuster Era and Conglomerate Hollywood", "description": "This section studies how Hollywood reorganized around high-concept films, saturation release, franchises, merchandising, and corporate media ownership.", "children": [{"id": "617fa88c-a7e8-40dd-bb3d-172d43b758b2", "type": "subtopic", "title": "Blockbuster economics", "children": [{"id": "58cb866c-b70b-4a95-964b-9883390c9b37", "type": "concept", "title": "Wide release and saturation marketing"}, {"id": "dafd8b92-96ec-49c4-89f7-06010add020a", "type": "concept", "title": "Merchandising and ancillary markets"}, {"id": "40d7d4e0-3130-4f81-a4a4-da9977724c1b", "type": "concept", "title": "Risk, spectacle, and event cinema"}], "description": "Students learn how Jaws, Star Wars, and franchise logic reshaped production and distribution."}, {"id": "c526a21f-8e9f-4f13-a9cc-9e9fa77dd30a", "type": "subtopic", "title": "High concept and genre spectacle", "children": [{"id": "02357bba-3ba9-4ca2-bac0-a2f7406e9892", "type": "concept", "title": "Pitchability and visual hooks"}, {"id": "60da43fa-1bc2-4472-8408-df8c0fc83175", "type": "concept", "title": "Action, sci-fi, fantasy, and family entertainment"}, {"id": "195f09e3-9d0c-4736-8078-319c887aaa8d", "type": "concept", "title": "Sound, effects, and affective scale"}], "description": "The gist is to see style, premise, and marketing as an integrated system."}, {"id": "3d0061f6-d99c-4aa5-b7c0-89773f6dea1f", "type": "subtopic", "title": "Conglomeration and synergy", "children": [{"id": "5d0d301f-bf7b-40c8-9bdf-bd7974d54c4f", "type": "concept", "title": "Corporate ownership and vertical integration revisited"}, {"id": "06a13243-21e9-4c6d-beb6-f9a130d45bd9", "type": "concept", "title": "Television, cable, music, games, and toys"}, {"id": "42ededfb-ff5c-4ded-a1fd-dd9412954f0e", "type": "concept", "title": "IP management and franchise world-building"}], "description": "Students connect film to broader media industries."}]}, {"id": "2801b2a4-9550-406c-9099-34d79d3ea823", "type": "topic", "title": "Independent American Cinema", "description": "Independent cinema offers alternative production models, regional stories, identity politics, and festival-based pathways outside or alongside Hollywood.", "children": [{"id": "e6d6420f-6441-41c2-8231-f2ba5ba41e71", "type": "subtopic", "title": "Indie institutions", "children": [{"id": "4544e27b-572c-4309-8bc4-1bb9f4a346a6", "type": "concept", "title": "Sundance and festival economies"}, {"id": "3d0ae19f-84f7-4d2f-9c05-194e70a1d637", "type": "concept", "title": "Miramax and specialty distribution"}, {"id": "70513ceb-9689-4ea7-bd89-eb2e51908d00", "type": "concept", "title": "Microbudget and regional production"}], "description": "Students learn how festivals, distributors, grants, and specialty divisions built independent film culture."}, {"id": "2b372a46-501d-439a-8c8c-e669b1d226fb", "type": "subtopic", "title": "Aesthetic and narrative alternatives", "children": [{"id": "47f0ed14-b549-45a1-acdd-3dc6e5c1b89e", "type": "concept", "title": "Minimalism, episodic structure, and character study"}, {"id": "bcff5ea3-1f24-4525-84b8-25f8bfd97d96", "type": "concept", "title": "Queer cinema and identity-based movements"}, {"id": "4bda317c-9c82-47b6-9bf1-ebbfa07a4209", "type": "concept", "title": "Documentary-fiction overlap"}], "description": "The point is to identify how independent films depart from classical and blockbuster norms."}, {"id": "f74ec082-e42d-42e0-9793-59e401ddf