ubtopic", "title": "Transnational style and circulation", "children": [{"id": "8e16e507-ff5e-403c-bf5d-a988b5fe02af", "type": "concept", "title": "Martial arts, horror, melodrama, and action"}, {"id": "9da646ad-0057-41a6-8272-1464cf874824", "type": "concept", "title": "Festival, remake, and streaming circulation"}, {"id": "7dd96405-883d-4089-b3f7-a81358cbb387", "type": "concept", "title": "Authorship, stars, and regional markets"}], "description": "Students track how Asian cinema shapes global genre, art cinema, and popular culture."}]}, {"id": "14928d6e-c871-47d1-a216-ff5290b88779", "type": "topic", "title": "African, Latin American, and Middle Eastern Cinemas", "description": "A top Film History II must build durable knowledge of cinemas historically marginalized in Euro-American survey models.", "children": [{"id": "3bde82f5-eb23-4209-9296-c5f0906a3e28", "type": "subtopic", "title": "African cinemas", "children": [{"id": "6bfc1d17-b7fc-41e7-855c-2b0d1ffdf710", "type": "concept", "title": "Senegalese and Francophone African cinema"}, {"id": "198e8b22-a6a2-446c-a1b4-d4976d121290", "type": "concept", "title": "Nollywood and popular video industries"}, {"id": "b82aa18c-5d96-4a29-a557-935faf1c3f60", "type": "concept", "title": "Postcolonial memory and social critique"}], "description": "Students learn how African filmmakers navigated colonial legacies, state support, oral traditions, and global festival circuits."}, {"id": "60421348-97c6-4efe-8160-0b087cf4b6eb", "type": "subtopic", "title": "Latin American cinemas", "children": [{"id": "9d713694-3366-429a-aa0f-6ab695f1b412", "type": "concept", "title": "Cinema Novo and Third Cinema"}, {"id": "c5725fc9-19b0-4327-ad3c-442db7deee5b", "type": "concept", "title": "Mexican, Argentine, Chilean, and Cuban contexts"}, {"id": "98be3f65-b9c7-4736-96e2-9f564d54b494", "type": "concept", "title": "New Latin American cinemas and festival recognition"}], "description": "The point is to connect film movements to dictatorship, revolution, poverty, memory, and popular culture."}, {"id": "09a2da7c-a4f0-4e1a-af9e-ceecdfb364cc", "type": "subtopic", "title": "Middle Eastern and Iranian cinemas", "children": [{"id": "632115e1-8b30-4937-ac83-1d5a07bc0a69", "type": "concept", "title": "Iranian art cinema"}, {"id": "e2a232ee-8ce8-4b6e-aa1d-1ae2eb0b89af", "type": "concept", "title": "Palestinian and diasporic cinema"}, {"id": "65cb4466-6733-4ba3-87c4-9bfaf2dd5529", "type": "concept", "title": "Egyptian popular cinema and regional industries"}], "description": "Students study censorship, allegory, realism, gender, religion, and transnational reception."}]}, {"id": "c6c26a69-e8f0-460b-9443-c88e771f1b0a", "type": "topic", "title": "Documentary Movements", "description": "This section examines documentary after World War II as a field of technology, ethics, observation, activism, television, and political memory.", "children": [{"id": "908c3a9a-3bc9-4e11-9dcb-8f519b8116a8", "type": "subtopic", "title": "Direct cinema and cinema verite", "children": [{"id": "f7263036-493f-4935-a2fc-9cb21f374abe", "type": "concept", "title": "Observation, performance, and presence"}, {"id": "9bb23475-96f9-433d-b710-9eb803bb9012", "type": "concept", "title": "Filmmaker intervention versus invisibility"}, {"id": "5431ec0f-9294-4db6-9260-e236cf0ff151", "type": "concept", "title": "Truth claims and editing"}], "description": "Students learn how lightweight cameras and sync sound changed nonfiction practice."}, {"id": "1f353b8b-2c25-4928-9ac0-65954b1df73f", "type": "subtopic", "title": "Political and essay documentary", "children": [{"id": "dbb90dc7-8371-44d9-ac25-cc16a875a87a", "type": "concept", "title": "Third Cinema and activist documentary"}, {"id": "e7385c1b-5ede-472e-b957-7e1d11eea579", "type": "concept", "title": "Essay film and first-person narration"}, {"id": "be8dee94-d616-4e83-aa6a-94e1b0587dd3", "type": "concept", "title": "Archives, memory, and trauma"}], "description": "The gist is to study documentary as argument, testimony, and historical intervention."}, {"id": "6d42a508-159f-44e2-8ad7-8ce50563ca74", "type": "subtopic", "title": "Contemporary nonfiction ecosystems", "children": [{"id": "d87cf815-44a3-46b2-83ce-f770f97eece3", "type": "concept", "title": "Docuseries and platform formats"}, {"id": "2e756023-f069-4595-a3b5-49ce17d61be0", "type": "concept", "title": "Ethics of representation and consent"}, {"id": "c566e054-64eb-495b-a578-b126f32ffc55", "type": "concept", "title": "Impact producing and public debate"}], "description": "Students connect documentary to television, festivals, streaming, true crime, and impact campaigns."}]}, {"id": "abf64ff0-9080-4d9a-84c7-a4aeecb3e1cb", "type": "topic", "title": "Experimental, Avant-Garde, and Essay Film", "description": "Experimental cinema challenges narrative, spectatorship, medium boundaries, and institutional definitions of film.", "children": [{"id": "e9201870-221a-4ad9-92f7-0f3d3d642af8", "type": "subtopic", "title": "Postwar avant-garde traditions", "children": [{"id": "29b9c934-3522-49b1-b42a-0ec789020ece", "type": "concept", "title": "Structural film"}, {"id": "0f4b2afe-a249-4a18-b056-388de0ba71d4", "type": "concept", "title": "Expanded cinema"}, {"id": "82540f6e-338e-4eeb-af20-cc7641755693", "type": "concept", "title": "Found footage and material film"}], "description": "Students learn how experimental filmmakers explored perception, materiality, duration, and embodiment."}, {"id": "f5acd7b9-38ca-4d59-9df9-4443d8cca1eb", "type": "subtopic", "title": "Video and time-based art", "children": [{"id": "37b78069-02c5-4168-86b0-afb7d89810e0", "type": "concept", "title": "Portapak and early video art"}, {"id": "f88f69a8-4c49-4d8e-95b5-4391e1728f65", "type": "concept", "title": "Projection, monitors, and installation contexts"}, {"id": "5270959d-23d4-45b2-b797-a2984559ecbb", "type": "concept", "title": "Performance and documentation"}], "description": "The point is to connect film history with gallery, performance, installation, and electronic media."}, {"id": "109e95c2-e9b9-4261-8b8e-c2db222d040c", "type": "subtopic", "title": "Essay film and hybrid forms", "children": [{"id": "b0749a4c-1b75-4586-8db1-f98b0725202b", "type": "concept", "title": "Voice, text, and image thinking"}, {"id": "f016b2e6-9646-4459-8bba-f50419246b06", "type": "concept", "title": "Personal and political memory"}, {"id": "9555619c-d3fd-41ff-b10a-d27e7993ec36", "type": "concept", "title": "Hybrid documentary-fiction structures"}], "description": "Students study works that combine argument, memory, archive, travel, and self-reflection."}]}, {"id": "828e85ba-761e-4697-a83d-4e12150a800b", "type": "topic", "title": "Feminist, Queer, Black, Indigenous, and Decolonial Film Histories", "description": "This section centers counter-histories, not as add-ons, but as necessary frameworks for understanding modern cinema.", "children": [{"id": "d3928cf5-47b4-4b08-9686-de9514bfac53", "type": "subtopic", "title": "Feminist film histories", "children": [{"id": "b469c972-e33d-462a-a7f7-2620b8962c9f", "type": "concept", "title": "Second-wave feminist film culture"}, {"id": "6a13c5f9-a88c-4f16-86f8-50c6a90bac1b", "type": "concept", "title": "Women directors, editors, writers, and producers"}, {"id": "fc57d9ec-e38e-49b0-80f6-b58a1196dec6", "type": "concept", "title": "The gaze, spectatorship, and critique"}], "description": "Students study women filmmakers, feminist criticism, labor, spectatorship, and representation."}, {"id": "8cc752a0-5875-4cd1-8713-b105c03e3d64", "type": "subtopic", "title": "Queer and Black film histories", "children": [{"id": "47149b49-51a8-46ec-9913-891a375dce85", "type": "concept", "title": "New Queer Cinema"}, {"id": "1d3467cb-6630-4ba2-b69b-1a81f941b0f5", "type": "concept", "title": "L.A. Rebellion and Black independent cinema"}, {"id": "d1abff14-d4a2-4b81-baa3-b96d472b488e", "type": "concept", "title": "Representation, authorship, and audience publics"}], "description": "The gist is to trace identity, form, community, market, and resistance."}, {"id": "09f4b8d0-0f77-45cd-81e3-9f2a966cce2c", "type": "subtopic", "title": "Indigenous and decolonial cinemas", "children": [{"id": "cce4ee94-cb00-4106-986e-1833c7183100", "type": "concept", "title": "Fourth Cinema and Indigenous media"}, {"id": "b80bc52e-bff2-436b-98db-f64547eaa2dc", "type": "concept", "title": "Decolonial documentary and fiction"}, {"id": "7bfe2a1e-6af0-445c-b2ca-ae456d241536", "type": "concept", "title": "Community accountability and cultural protocols"}], "description": "Students examine sovereignty, land, language, memory, and anti-colonial image-making."}]}, {"id": "33699744-184f-4d40-a439-06afb40b190c", "type": "topic", "title": "Television, Video, and Media Convergence", "description": "Film history after 1960 cannot be separated from television, home video, music video, cable, games, and digital convergence.", "children": [{"id": "47c7dd4d-3046-4f4b-bc73-2fd37af35c00", "type": "subtopic", "title": "Television and film culture", "children": [{"id": "323dc9b8-c4c6-4fe0-ac75-d28829952525", "type": "concept", "title": "Broadcast competition and made-for-TV movies"}, {"id": "cd604aba-33c5-46ba-a66f-ebbd5d4dc567", "type": "concept", "title": "Cable, HBO, and prestige television"}, {"id": "1dcec09d-4d57-49bc-9958-5a8c31e9391c", "type": "concept", "title": "Seriality and long-form storytelling"}], "description": "Students learn how television changed audiences, financing, aesthetics, and prestige."}, {"id": "6af09939-4244-4248-980a-224705256e5c", "type": "subtopic", "title": "Home video and cinephilia", "children": [{"id": "751e460e-54a3-4a80-8621-a959cf9809dc", "type": "concept", "title": "Rental culture and video stores"}, {"id": "a5babc57-14fe-47d0-aa34-56fde0fc29a2", "type": "concept", "title": "DVD extras and cinephile education"}, {"id": "5be88a48-08e2-41ae-9047-4f195106d01d", "type": "concept", "title": "Cult film and midnight movie circulation"}], "description": "The point is to understand VHS, DVD, and boutique labels as historical forces."}, {"id": "014e2381-103e-4b99-a2e6-c2ceb26c32fc", "type": "subtopic", "title": "Convergence and transmedia", "children": [{"id": "fa83242d-77f7-4a9d-a10f-1d4407b6b99c", "type": "concept", "title": "Music video and advertising aesthetics"}, {"id": "bcd06a3a-e528-4c7a-be2a-351337d0c37f", "type": "concept", "title": "Games, comics, and franchise worlds"}, {"id": "8ac57ef8-946b-45cc-bb79-5da5dbbfcc68", "type": "concept", "title": "Participatory fandom and online communities"}], "description": "Students connect film to wider media systems."}]}, {"id": "b4c3b509-c9c0-4bc7-8bb1-cc8ac0523a8f", "type": "topic", "title": "The Digital Cinema Revolution", "description": "Digital technologies changed production, post-production, distribution, exhibition, preservation, and the look of moving images.", "children": [{"id": "a26947ff-ee21-47da-8d08-66815172268e", "type": "subtopic", "title": "Digital production and post-production", "children": [{"id": "93a6b3fd-0a93-4963-88d9-5146da3b8808", "type": "concept", "title": "DV, HD, and digital cinematography"}, {"id": "2acee5e9-adbe-4b82-a742-097f84be738b", "type": "concept", "title": "Nonlinear editing and compositing"}, {"id": "8734c43f-24bc-40df-981c-49d8a76421fb", "type": "concept", "title": "Digital color grading and DI workflows"}], "description": "Students learn how digital cameras, editing systems, VFX, and color workflows changed filmmaking."}, {"id": "4429517e-ae36-4bcb-9fc6-39aae9730f8d", "type": "subtopic", "title": "Digital aesthetics", "children": [{"id": "3dd9f01b-b569-45a5-aab6-6f66755e454b", "type": "concept", "title": "CGI and photorealism"}, {"id": "5c4f3091-9174-401c-ab4a-8af2f54a943c", "type": "concept", "title": "Motion capture and virtual production"}, {"id": "6b3b44d5-f658-4a59-b4d4-caf5f8222013", "type": "concept", "title": "Low-budget digital realism"}], "description": "The gist is to study how digital tools changed realism, spectacle, movement, and time."}, {"id": "0fcff154-8226-4814-9d54-f42eb45cdb0f", "type": "subtopic", "title": "Distribution and exhibition change", "children": [{"id": "0c877e00-6685-42a6-83a2-7bc094ae66bc", "type": "concept", "title": "Digital projection"}, {"id": "59679fdc-331f-4e8f-8f01-5398b45df31a", "type": "concept", "title": "Online circulation and piracy"}, {"id": "120463f4-1541-4482-9227-e87d29ecad08", "type": "concept", "title": "DCP, restoration, and preservation challenges"}], "description": "Students connect digital cinema to theaters, festivals, piracy, and global access."}]}, {"id": "7d1390bf-a275-40a4-82a8-d6995118931c", "type": "topic", "title": "Contemporary Global Cinema", "description": "This section treats contemporary cinema as a network of national industries, festivals, platforms, diasporas, auteurs, genres, and uneven power.", "children": [{"id": "53685ccb-51ca-45e5-9579-a58eee2e3c1a", "type": "subtopic", "title": "Global auteurs and festival cinema", "children": [{"id": "589cdad2-c1e9-4ecd-867b-5775140c696e", "type": "concept", "title": "Festival discovery and awards economies"}, {"id": "26b56da4-8dbc-4a87-a4be-9da0e15983d2", "type": "concept", "title": "Slow cinema and contemplative style"}, {"id": "b944ef6a-7aac-4407-b81a-6f33522c2e4b", "type": "concept", "title": "Global art-house branding"}], "description": "Students learn how contemporary prestige cinema is produced, circulated, and valued."}, {"id": "296ece35-d3f6-4982-aa39-dbb1a008b862", "type": "subtopic", "title": "Popular global industries", "children": [{"id": "1b74dcab-7761-44be-ae0e-202a5792b61a", "type": "concept", "title": "Bollywood, Nollywood, Korean cinema, and Chinese markets"}, {"id": "2c805d0f-5db7-441a-b33a-25b104f45d13", "type": "concept", "title": "Regional genres and stars"}, {"id": "ed88bf32-e8f3-4b0f-876e-c2bd8f50ed7b", "type": "concept", "title": "Cross-border remakes and co-productions"}], "description": "The point is to study popular film industries with their own histories and logics."}, {"id": "f71c2ee8-c47d-46c1-a687-7f004ccf2a6f", "type": "subtopic", "title": "Migration, diaspora, and transnational identity", "children": [{"id": "f81bc477-71e9-4d9a-917f-34d51b28436f", "type": "concept", "title": "Exile, migration, and memory"}, {"id": "830db4f2-4b26-4c3b-b215-afbafea134ef", "type": "concept", "title": "Diasporic spectatorship"}, {"id": "5bc36d5b-072f-4e7a-9efe-d15939fe5d8a", "type": "concept", "title": "Language, hybridity, and belonging"}], "description": "Students analyze films that cross borders thematically and industrially."}]}, {"id": "b3face90-8f34-4a56-bc82-48b049e283a9", "type": "topic", "title": "Streaming and the Changing Industry", "description": "Streaming reorganized film culture around platforms, algorithms, subscription libraries, data, global releases, and changing theatrical norms.", "children": [{"id": "32112b5a-33e9-4f22-b86c-c60e6794e549", "type": "subtopic", "title": "Platform power", "children": [{"id": "b60057bd-1db8-4fc7-b4d3-8c76e50eb536", "type": "concept", "title": "Netflix, Amazon, Disney, Apple, and platform competition"}, {"id": "47ff7016-5d20-4e7f-a82b-645b2b059abc", "type": "concept", "title": "Recommendation systems and datafication"}, {"id": "10cb0a0d-f2d1-48ad-a134-49befe516c15", "type": "concept", "title": "Global originals and localization"}], "description": "Students learn how streamers shape financing, visibility, taste, and global circulation."}, {"id": "aa7c2337-cdaa-42c1-8ded-bcc9c1ffb516", "type": "subtopic", "title": "Theatrical, festival, and release windows", "children": [{"id": "d6de1f90-52a1-4e7c-a0e8-1e9a072cd066", "type": "concept", "title": "Day-and-date release"}, {"id": "6e66d1de-aea9-4598-8eba-10f6f45b0ee8", "type": "concept", "title": "Windowing and theatrical exclusivity"}, {"id": "ecebf9d5-d94c-4004-bb55-6913378a84b7", "type": "concept", "title": "Festival acquisitions and streaming premieres"}], "description": "The gist is to track how release strategies changed in the platform era."}, {"id": "0149c1a8-533f-4fd6-bf03-1a3ed7af55b8", "type": "subtopic", "title": "Labor, access, and cultural memory", "children": [{"id": "ce62c869-dfd4-41ed-a1d0-317b7e33649e", "type": "concept", "title": "Residuals, strikes, and creative labor"}, {"id": "4c7bb4b1-bb97-4a7f-a09b-5a161492c3de", "type": "concept", "title": "Catalog instability and disappearance"}, {"id": "e309c2b1-56c3-42f1-838c-5d35be24a404", "type": "concept", "title": "Accessibility, subtitling, dubbing, and global publics"}], "description": "Students evaluate the consequences of digital abundance and platform control."}]}, {"id": "21637c7d-a5f5-4844-933c-7be4eb447d44", "type": "topic", "title": "Archives, Restoration, and Canon Formation in the Modern Era", "description": "Modern film history depends on what is preserved, restored, subtitled, programmed, streamed, taught, and made available.", "children": [{"id": "2b029995-7851-4d57-9aa0-c4b38298ee4d", "type": "subtopic", "title": "Restoration and preservation", "children": [{"id": "074efeff-b63e-43fc-b57a-24aab1e46174", "type": "concept", "title": "Analog-to-digital restoration"}, {"id": "6d2be596-c2d7-4f4d-bbb4-830494ea117e", "type": "concept", "title": "Born-digital fragility"}, {"id": "a7e1ac49-00d2-41d2-8013-34db9b35f87c", "type": "concept", "title": "Color, sound, aspect ratio, and version choices"}], "description": "Students learn how modern and digital cinema create new preservation challenges."}, {"id": "aa52e453-9c35-4c1f-b30e-3a2d2a9eb067", "type": "subtopic", "title": "Archives and curatorial power", "children": [{"id": "f2d519c7-d317-47cd-aeda-0fe79610f7de", "type": "concept", "title": "National archives, university archives, and private collections"}, {"id": "687a79fc-4d0b-444b-9427-4a85a2ff84ff", "type": "concept", "title": "Criterion, BFI, UCLA, LOC, and boutique distribution"}, {"id": "3e3aa7aa-d920-4f44-99f1-eb84507d605a", "type": "concept", "title": "Rights, access, and programming"}], "description": "The point is to understand institutions as active makers of film history."}, {"id": "d59d031b-c0ab-4644-b74e-399bc0c69659", "type": "subtopic", "title": "Canon revision", "children": [{"id": "34b8e5ae-25eb-4946-aef1-ae7a35166608", "type": "concept", "title": "Women, Black, queer, Indigenous, and global canons"}, {"id": "899ca959-617a-48e9-857c-3142ba107e1f", "type": "concept", "title": "Festival and critic poll influence"}, {"id": "cc7c6a33-c931-4c09-a2a9-a08a5cd3336c", "type": "concept", "title": "Pedagogical selection and historical responsibility"}], "description": "Students practice questioning inherited lists and syllabi."}]}, {"id": "b5f4b11b-534a-4fbd-8cac-5dc5bb432ea4", "type": "topic", "title": "Modern Film-History Research Capstone", "description": "The capstone asks students to produce a historically grounded argument about modern or contemporary cinema using film analysis, sources, and context.", "children": [{"id": "e97d3326-237a-4fdc-91bc-94a1f5907e33", "type": "subtopic", "title": "Research design", "children": [{"id": "16723452-8502-4fd4-864e-d8e17bc7ee62", "type": "concept", "title": "Topic scope and case selection"}, {"id": "d4defbc7-e35a-4c57-9109-e84b2892b3c5", "type": "concept", "title": "Annotated bibliography and source map"}, {"id": "63212958-6e66-49d1-8057-5be809e8092d", "type": "concept", "title": "Historical stakes and research contribution"}], "description": "Students develop a focused question that can be answered with films, scholarship, criticism, archives, and industry evidence."}, {"id": "b00ba3f2-6212-4017-97f0-0af74f811e2f", "type": "subtopic", "title": "Evidence and analysis", "children": [{"id": "10c3d70e-2dea-4f3c-8345-5903c6ac398d", "type": "concept", "title": "Sequence analysis"}, {"id": "22ec39de-2f2d-4b1c-89eb-4187afd1b588", "type": "concept", "title": "Reception and industry evidence"}, {"id": "105c467a-2a94-41d4-a3f6-255041f4fd7c", "type": "concept", "title": "Comparative or transnational framing"}], "description": "The focus is on connecting film form to history rather than summarizing plots or movements."}, {"id": "7c6b0349-a9a0-421b-9ffc-630d2d20ede9", "type": "subtopic", "title": "Final paper and presentation", "children": [{"id": "bfe490b2-2ced-42cd-a656-eba5ae24d014", "type": "concept", "title": "Clip or still-based oral presentation"}, {"id": "041f08aa-c9ca-4892-916c-2ebc2dfcf512", "type": "concept", "title": "Research paper with revision"}, {"id": "52960871-28e7-43b1-830b-2cbb4cc9b4a4", "type": "concept", "title": "Reflection on archive, canon, and method"}], "description": "Students communicate a polished argument for a film-studies audience."}]}], "dbBacked": true}$fh2json$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'film-history-ii'
);

update public.learning_paths
set
  title = 'Film History II',
  goal = 'Film History II',
  summary = 'This syllabus preserves a French New Wave-to-streaming arc while adding postwar art cinema, Third Cinema, African/Latin American/Middle Eastern cinemas, feminist/queer/Black/Indigenous/decolonial histories, video/time-based media, archive practice, and a research capstone.',
