rnisms", "children": [{"id": "14ed0fd5-826e-4861-89d3-cf1e40d10139", "type": "concept", "title": "Japanese New Wave"}, {"id": "91b60540-0191-4f53-b9ec-ba45494ff903", "type": "concept", "title": "Indian parallel cinema"}, {"id": "c0bd7634-fa91-4402-a657-fd7581b58db0", "type": "concept", "title": "African and Middle Eastern modernist cinemas"}], "description": "Students study modern cinema beyond a Euro-American frame."}]}, {"id": "f72dd010-9f0f-4487-a0af-cf8764e8f246", "type": "topic", "title": "New Hollywood, 1967-1980", "description": "New Hollywood marks a major transformation in American cinema through youth audiences, auteur branding, genre revision, political disillusionment, and industry crisis.", "children": [{"id": "0ceab760-2bb4-442b-bbd3-e717caea4aff", "type": "subtopic", "title": "Industrial crisis and opportunity", "children": [{"id": "b65140a8-0683-45e2-84bb-a0ade0811313", "type": "concept", "title": "Paramount decrees and studio restructuring"}, {"id": "497d55a8-9032-4473-9cda-3f6fe8a95b43", "type": "concept", "title": "Television competition and youth markets"}, {"id": "1b6279fa-e5bb-43f1-96dd-83ce416ff615", "type": "concept", "title": "Ratings system and changing censorship"}], "description": "Students learn how declining studio control opened space for new filmmakers and subjects."}, {"id": "33841f5b-6cb5-4b48-82b2-b8eb016881ff", "type": "subtopic", "title": "Auteurism and genre revision", "children": [{"id": "597a457b-12e5-4aa1-a352-640fd477b257", "type": "concept", "title": "Road movie, western, crime, horror, and melodrama revision"}, {"id": "69d4feeb-bf59-4426-b3e4-9d91054084f5", "type": "concept", "title": "Ambiguous protagonists and antiheroes"}, {"id": "9082ba62-cca9-4ff5-ba12-e0f0b62746c1", "type": "concept", "title": "Violence, sexuality, and political distrust"}], "description": "The point is to connect European art cinema and American genre tradition."}, {"id": "7b1cb957-f3ff-4a92-aa95-d64ce7878e7e", "type": "subtopic", "title": "Race, gender, and counterculture", "children": [{"id": "4bf4c4ac-10e9-41c7-a377-08604cd0e2d6", "type": "concept", "title": "Blaxploitation and independent Black cinema"}, {"id": "6e7c8a4e-5391-438c-99f4-f460c80a7179", "type": "concept", "title": "Women filmmakers and feminist critique"}, {"id": "826ca07d-a2b6-4101-a4a6-6a551b2c72dd", "type": "concept", "title": "Vietnam, Watergate, and social fracture"}], "description": "Students examine the period's promises and blind spots."}]}, {"id": "d7864845-513e-4e96-a4a0-b3e843c6c830", "type": "topic", "title": "The Blockbuster Era and Conglomerate Hollywood", "description": "This section studies how Hollywood reorganized around high-concept films, saturation release, franchises, merchandising, and corporate media ownership.", "children": [{"id": "617fa88c-a7e8-40dd-bb3d-172d43b758b2", "type": "subtopic", "title": "Blockbuster economics", "children": [{"id": "58cb866c-b70b-4a95-964b-9883390c9b37", "type": "concept", "title": "Wide release and saturation marketing"}, {"id": "dafd8b92-96ec-49c4-89f7-06010add020a", "type": "concept", "title": "Merchandising and ancillary markets"}, {"id": "40d7d4e0-3130-4f81-a4a4-da9977724c1b", "type": "concept", "title": "Risk, spectacle, and event cinema"}], "description": "Students learn how Jaws, Star Wars, and franchise logic reshaped production and distribution."}, {"id": "c526a21f-8e9f-4f13-a9cc-9e9fa77dd30a", "type": "subtopic", "title": "High concept and genre spectacle", "children": [{"id": "02357bba-3ba9-4ca2-bac0-a2f7406e9892", "type": "concept", "title": "Pitchability and visual hooks"}, {"id": "60da43fa-1bc2-4472-8408-df8c0fc83175", "type": "concept", "title": "Action, sci-fi, fantasy, and family entertainment"}, {"id": "195f09e3-9d0c-4736-8078-319c887aaa8d", "type": "concept", "title": "Sound, effects, and affective scale"}], "description": "The gist is to see style, premise, and marketing as an integrated system."}, {"id": "3d0061f6-d99c-4aa5-b7c0-89773f6dea1f", "type": "subtopic", "title": "Conglomeration and synergy", "children": [{"id": "5d0d301f-bf7b-40c8-9bdf-bd7974d54c4f", "type": "concept", "title": "Corporate ownership and vertical integration revisited"}, {"id": "06a13243-21e9-4c6d-beb6-f9a130d45bd9", "type": "concept", "title": "Television, cable, music, games, and toys"}, {"id": "42ededfb-ff5c-4ded-a1fd-dd9412954f0e", "type": "concept", "title": "IP management and franchise world-building"}], "description": "Students connect film to broader media industries."}]}, {"id": "2801b2a4-9550-406c-9099-34d79d3ea823", "type": "topic", "title": "Independent American Cinema", "description": "Independent cinema offers alternative production models, regional stories, identity politics, and festival-based pathways outside or alongside Hollywood.", "children": [{"id": "e6d6420f-6441-41c2-8231-f2ba5ba41e71", "type": "subtopic", "title": "Indie institutions", "children": [{"id": "4544e27b-572c-4309-8bc4-1bb9f4a346a6", "type": "concept", "title": "Sundance and festival economies"}, {"id": "3d0ae19f-84f7-4d2f-9c05-194e70a1d637", "type": "concept", "title": "Miramax and specialty distribution"}, {"id": "70513ceb-9689-4ea7-bd89-eb2e51908d00", "type": "concept", "title": "Microbudget and regional production"}], "description": "Students learn how festivals, distributors, grants, and specialty divisions built independent film culture."}, {"id": "2b372a46-501d-439a-8c8c-e669b1d226fb", "type": "subtopic", "title": "Aesthetic and narrative alternatives", "children": [{"id": "47f0ed14-b549-45a1-acdd-3dc6e5c1b89e", "type": "concept", "title": "Minimalism, episodic structure, and character study"}, {"id": "bcff5ea3-1f24-4525-84b8-25f8bfd97d96", "type": "concept", "title": "Queer cinema and identity-based movements"}, {"id": "4bda317c-9c82-47b6-9bf1-ebbfa07a4209", "type": "concept", "title": "Documentary-fiction overlap"}], "description": "The point is to identify how independent films depart from classical and blockbuster norms."}, {"id": "f74ec082-e42d-42e0-9793-59